import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type InstaLikeCountProps = Record<string, any>;

const HeartIcon: React.FC<{ color: string; size: number }> = ({ color, size }) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 24 24"
    fill={color}
    style={{
      display: "block",
    }}
  >
    <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
  </svg>
);

const InstaLikeCount: React.FC<InstaLikeCountProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  iconColor = "#ed4956",
  textColor = "#262626",
  startCount = 18,
  endCount = 7214,
  durationInSeconds = 5,
  heartSize = 180,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color parser safety
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Timing
  // We want the count to happen primarily in the first 60-70% of the video
  const countDurationFrames = fps * (durationInSeconds * 0.7);
  
  // Easing: Start slow, go very fast in middle, slow down at end (EaseInOutExp)
  const progress = interpolate(
    frame,
    [0, countDurationFrames],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.22, 1, 0.36, 1), // Custom ease for "viral" feel
    }
  );

  const currentCount = Math.floor(
    interpolate(progress, [0, 1], [startCount, endCount])
  );

  // Blur Effect Logic
  // Blur peaks when the numbers are changing the fastest (in the middle of the ease)
  // We approximate velocity by checking the distance from the middle of the animation
  const blurIntensity = interpolate(
    progress,
    [0, 0.2, 0.8, 1],
    [0, 4, 4, 0], // Blur heavily during the fast climb
    { extrapolateRight: "clamp" }
  );

  // Heart Pulse Animation
  // Subtly pulses in sync with the climb
  // Frequency increases slightly as it goes up
  const pulseFreq = interpolate(progress, [0, 1], [0.2, 0.8]);
  const pulseScale = Math.sin(frame * pulseFreq) * 0.05 + 1; // +/- 5% scale

  // Initial Spring Pop for the heart appearing
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 12 },
  });

  const finalHeartScale = entranceSpring * pulseScale;

  // Formatting number with commas (e.g. 7,214)
  const formattedNumber = currentCount.toLocaleString("en-US");

  // Font size relative to heart size
  const fontSize = heartSize * 0.6;
  const gap = heartSize * 0.2;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Inter, sans-serif",
        flexDirection: "column",
        gap: gap,
      }}
    >
      {/* Heart Container */}
      <div
        style={{
          transform: `scale(${finalHeartScale})`,
          // Combine transformations nicely
        }}
      >
        <HeartIcon color={iconColor} size={heartSize} />
      </div>

      {/* Number Container */}
      <div
        style={{
          color: textColor,
          fontSize: fontSize,
          fontWeight: 700,
          filter: `blur(${blurIntensity}px)`,
          opacity: interpolate(frame, [0, 10], [0, 1]), // Quick fade in
          fontVariantNumeric: "tabular-nums", // Keeps numbers from jittering width
          textAlign: "center",
          lineHeight: 1,
        }}
      >
        {formattedNumber}
      </div>
    </AbsoluteFill>
  );
};

export default InstaLikeCount;